TT125-072.original_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>

SELECT (SUM(?amount) AS ?net_cash_flow)
WHERE {
  ?cf a wm:CashFlow ;
      wm:date ?date ;
      wm:amount ?amount ;
      wm:cashFlowOfInvestor ?inv .
  FILTER(?date >= "2024-01-01" && ?date <= "2024-12-31") .
  ?inv a wm:Investor ;
       wm:riskTolerance ?rt .
  FILTER(LCASE(?rt) = "aggressive") .
}

