TT125-084.original_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
WHERE {
  ?cf a wm:CashFlow ;
      wm:amount ?amount ;
      wm:date ?date ;
      wm:cashFlowOfInvestor ?inv .
  ?inv wm:segment ?seg .
  FILTER(?date >= "2025-01-01" && ?date <= "2025-12-31")
  FILTER(LCASE(?seg) = "diversified")
}

